```java
// Java 17 + Spring Boot 3.2 — jakarta.persistence
import jakarta.persistence.*;
import java.util.*;

// OneToOne: User has one Profile
@Entity
class User {
    @Id @GeneratedValue private Long id;
    private String username;

    @OneToOne(cascade = CascadeType.ALL)
    @JoinColumn(name = "profile_id") // owning side: holds the FK
    private Profile profile;
}

// OneToMany / ManyToOne: Department has many Employees
@Entity
class Department {
    @Id @GeneratedValue private Long id;
    private String name;

    @OneToMany(mappedBy = "department") // inverse side
    private List<Employee> employees = new ArrayList<>();
}

@Entity
class Employee {
    @Id @GeneratedValue private Long id;
    private String name;

    @ManyToOne
    @JoinColumn(name = "department_id") // owning side: holds the FK
    private Department department;
}

// ManyToMany: Student enrolls in many Courses
@Entity
class Student {
    @Id @GeneratedValue private Long id;
    private String name;

    @ManyToMany
    @JoinTable(name = "student_course",
        joinColumns = @JoinColumn(name = "student_id"),
        inverseJoinColumns = @JoinColumn(name = "course_id"))
    private Set<Course> courses = new HashSet<>();
}

@Entity
class Course {
    @Id @GeneratedValue private Long id;
    private String title;

    @ManyToMany(mappedBy = "courses") // inverse side
    private Set<Student> students = new HashSet<>();
}
```
The `@JoinColumn`/`@JoinTable` side always owns the relationship; the `mappedBy` side is read-only navigation.

