@Entity
class Order {
    @Id @GeneratedValue private Long id;
    private String orderNumber;

    // Inverse side: mappedBy points to the 'order' field in OrderItem
    @OneToMany(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<OrderItem> items = new ArrayList<>();

    // Helper keeps BOTH sides in sync in memory
    public void addItem(OrderItem item) {
        items.add(item);
        item.setOrder(this); // set the owning side — this is what persists
    }
}

@Entity
class OrderItem {
    @Id @GeneratedValue private Long id;
    private String productName;
    private int quantity;

    // Owning side: has @JoinColumn, controls the FK column
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id", nullable = false)
    private Order order;

    public void setOrder(Order order) { this.order = order; }
}
// Without mappedBy, Hibernate would create BOTH:
//   1. order_item.order_id (from @ManyToOne)
//   2. an order_items join table (from @OneToMany)
```

