@Entity
class Order {
    @Id @GeneratedValue private Long id;

    @ManyToOne
    @JoinColumn(name = "customer_id") // owning side, the only side
    private Customer customer;
}

@Entity
class Customer {
    @Id @GeneratedValue private Long id;
    private String name;
    // no List<Order> — you can't navigate customer -> orders in Java
}
// No mappedBy, no sync code, no JSON loop. Simplest possible mapping.
