@Entity
class BlogPost {
    @Id @GeneratedValue private Long id;
    private String title;

    @OneToMany(mappedBy = "post",
               cascade = CascadeType.ALL, // delete post -> delete comments
               orphanRemoval = true)      // remove from list -> delete comment
    private List<Comment> comments = new ArrayList<>();

    public void removeComment(Comment c) {
        comments.remove(c); // orphanRemoval fires on flush
        c.setPost(null);
    }
    public List<Comment> getComments() { return comments; }
}

@Entity
class Comment {
    @Id @GeneratedValue private Long id;
    private String text;

    @ManyToOne @JoinColumn(name = "post_id")
    private BlogPost post;
    public void setPost(BlogPost post) { this.post = post; }
}

// Scenario A: parent survives, child is orphaned -> orphanRemoval deletes it
var post = postRepository.findById(1L).orElseThrow();
post.removeComment(post.getComments().get(0));
postRepository.save(post); // DELETE issued for that one comment

// Scenario B: parent deleted -> CascadeType.REMOVE deletes every comment
postRepository.delete(post);
